const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const START = '2018-01-01';
    const END = '2019-01-01';
    const regionName = 'District of Columbia';
    const states = ee.FeatureCollection('TIGER/2018/States');
    const dc = states.filter(ee.Filter.eq('NAME', regionName));
    const geom = dc.geometry();

    // 2. Data Acquisition & Check
    let datasetUsed = null;
    let annualImg = null;

    const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(START, END)
      .filterBounds(geom);
    const chirpsCount = await chirps.size().getInfo();
    console.log(`CHIRPS images: ${chirpsCount}`);

    if (chirpsCount > 0) {
      annualImg = chirps.sum().select('precipitation'); // mm over 2018
      datasetUsed = 'CHIRPS Daily (mm)';
    } else {
      const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY')
        .filterDate(START, END)
        .select('total_precipitation')
        .filterBounds(geom);
      const era5Count = await era5.size().getInfo();
      console.log(`ERA5-Land Monthly images: ${era5Count}`);
      if (era5Count === 0) {
        console.log('No images found for 2018 in region.');
        console.log('C1');
        return;
      }
      const era5Sum_mm = era5.sum().multiply(1000).rename('precipitation'); // meters -> mm
      annualImg = era5Sum_mm;
      datasetUsed = 'ERA5-Land Monthly (mm)';
    }

    // 3. Processing & Valid Pixels Check
    const pxCount = await annualImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9,
    }).get('precipitation').getInfo();

    const validPx = (pxCount === null) ? 0 : pxCount;
    console.log(`Valid pixels: ${validPx}`);
    if (!validPx || validPx === 0) {
      console.log('No valid pixels after processing.');
      console.log('C2');
      return;
    }

    // 4. Calculation
    const totalMm = await annualImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 5000,
      maxPixels: 1e9,
    }).get('precipitation').getInfo();

    if (totalMm === null || !isFinite(totalMm)) {
      console.log('Calculation failed (null/NaN).');
      console.log('C3');
      return;
    }

    const inches = totalMm / 25.4;
    console.log(`Region: ${regionName}`);
    console.log(`Dataset: ${datasetUsed}`);
    console.log(`2018 Total Precip (area-avg): ${totalMm.toFixed(1)} mm (${inches.toFixed(2)} in)`);
    console.log(`Threshold: 50 in (1270.0 mm)`);
    console.log(`Meets threshold: ${inches >= 50 ? 'Yes' : 'No'}`);

    // 5. Final Answer Tag
    console.log(inches >= 50 ? 'A' : 'B');
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
